mapper.select:
SELECT accountAuth.`id` AS 'id', accountAuth.`account_id` AS 'accountId', accountAuth.`auth_type` AS 'authType', accountAuth.`auth_key` AS 'authKey', accountAuth.`auth_secret` AS 'authSecret', accountAuth.`fail_count` AS 'failCount', accountAuth.`max_fail_count` AS 'maxFailCount', accountAuth.`lock_until` AS 'lockUntil', accountAuth.`last_auth_time` AS 'lastAuthTime', accountAuth.`last_auth_ip` AS 'lastAuthIp', accountAuth.`status` AS 'status', accountAuth.`expire_time` AS 'expireTime', accountAuth.`create_time` AS 'createTime', accountAuth.`update_time` AS 'updateTime' FROM bds_account_auth accountAuth
AND accountAuth.`account_id` IN
#{accountId}
AND accountAuth.`auth_type` = #{authType}
AND accountAuth.`auth_key` = #{authKey}
AND accountAuth.`status` = #{status}
